// simple allocator with wear leveling
// uses a lookahead buffer to reduce scanning
while (true) {
    // find next free block
    while (lfs->free.off < lfs->cfg->block_count) {
        lfs_block_t off = lfs->free.off;
        lfs_size_t i = off / 32;
        lfs_size_t j = off % 32;

        // scan for next free bit
        while (i < lfs->cfg->block_count/32) {
            uint32_t *buffer = lfs->free.buffer;
            if (i < lfs->free.size) {
                uint32_t b = ~buffer[i];
                if (b && (b >> j)) {
                    b &= -(1u << j);
                    lfs->free.off = (i*32) + lfs_ctz(b);
                    *block = lfs->free.off;
                    lfs->free.off += 1;
                    return 0;
                }
            }

            // next word
            i += 1;
            j = 0;
        }

        // refill lookahead buffer
        if (lfs->free.i != lfs->free.size) {
            lfs->free.i = lfs->free.size;
        }

        // scan for free blocks
        lfs_block_t cycle = lfs->free.ack - lfs->free.begin;
        lfs_block_t begin = lfs->free.begin + cycle;
        lfs_block_t end = lfs->free.end + cycle;

        // scan metadata pairs
        lfs_block_t block = begin;
        while (block < end) {
            lfs_block_t diff = lfs_min(32*lfs->free.size, end-block);
            lfs_size_t i = 0;
            while (i < diff/32) {
                lfs->free.buffer[i] = 0xffffffff;
                i += 1;
            }

            // scan directory
            lfs_dir_t dir;
            int err = lfs_dir_fetch(lfs, &dir, (const lfs_block_t[2]){0, 1});
            if (err) {
                return err;
            }

            // mark used blocks
            while (true) {
                struct lfs_mattr attrs;
                err = lfs_dir_getslice(lfs, &dir, LFS_MATTRS(attrs), 
                    LFS_MATTRS_LIST, 0, &attrs, sizeof(attrs));
                if (err == LFS_ERR_NOENT) {
                    break;
                }
                if (err) {
                    return err;
                }

                if (attrs.type == LFS_TYPE_STRUCT) {
                    lfs_block_t b = attrs.u.data[0];
                    if (b >= block && b < block+diff) {
                        lfs->free.buffer[(b-block)/32] &= ~(1u << ((b-block)%32));
                    }
                }
            }

            block += diff;
        }

        lfs->free.begin = begin;
        lfs->free.end = end;
        lfs->free.off = begin;
    }

    // no space
    return LFS_ERR_NOSPC;
}

